// HasReversedEntry applies the HasEdge predicate on the "reversed_entry" edge.
func HasReversedEntry() predicate.ProgressionLedgerEntry {
	return predicate.ProgressionLedgerEntry(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2O, true, ReversedEntryTable, ReversedEntryColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasReversedEntryWith applies the HasEdge predicate on the "reversed_entry" edge with a given conditions (other predicates).
func HasReversedEntryWith(preds ...predicate.ProgressionLedgerEntry) predicate.ProgressionLedgerEntry {
	return predicate.ProgressionLedgerEntry(func(s *sql.Selector) {
		step := newReversedEntryStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

